-- ----------------------------
-- Table structure for `accounts`
-- ----------------------------
DROP TABLE IF EXISTS `accounts`;
CREATE TABLE `accounts` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `name` varchar(250) NOT NULL,
  `lead_type` varchar(25) NOT NULL COMMENT 'lead_type = {person,corporate}',
  `phone_number` varchar(100) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `cp_name` varchar(150) DEFAULT NULL,
  `lead_id` int(10) DEFAULT NULL,
  `stage_id` int(10) NOT NULL COMMENT 'stage = {Lead, Contact, Prospect, Followup, Meeting, Negotation, Close}',
  `status_id` int(10) NOT NULL COMMENT 'status_id = {0=Pending (Lead), 10=unreachable, 11= contacted, 20=Not interested so unqualified, 21=Interested so Qualified, 40=Followup (neutral result), 41= Followup (lower interest result), 42 = followup (higher intererest), 50=Meeting, 60=Negotation, 60= Close Lost, 61=Close Win  }',
  `inactive` tinyint(6) DEFAULT 0,
  `create_uid` int(10) DEFAULT NULL,
  `create_user` varchar(50) DEFAULT NULL,
  `create_date` time DEFAULT NULL,
  `package_id` int(10) DEFAULT NULL,
  `branch_id` int(10) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of accounts
-- ----------------------------

