-- ----------------------------
-- Table structure for `loans`
-- ----------------------------
DROP TABLE IF EXISTS `loans`;
CREATE TABLE `loans` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `branch_id` int(10) NOT NULL,
  `com_branch_id` int(10) DEFAULT 1,
  `loan_app_id` int(10) DEFAULT NULL,
  `code` varchar(25) DEFAULT '',
  `principal` decimal(10,2) DEFAULT 0.00,
  `monthly_interest_rate` decimal(10,2) NOT NULL,
  `payback_method_id` tinyint(6) DEFAULT NULL COMMENT 'collection_rule = "loose" => payment can be any time within a month and user can assign any amount to be interest and principle when receiving payment ',
  `borrower_id` int(10) NOT NULL COMMENT 'person_id that is borrower',
  `referrer_id` int(10) DEFAULT NULL,
  `effective_date` date DEFAULT NULL,
  `period_months` decimal(10,2) DEFAULT NULL,
  `maturity_date` date DEFAULT NULL,
  `first_pmt_date` date DEFAULT NULL,
  `allow_add` tinyint(6) NOT NULL DEFAULT 1,
  `allow_reschedule` tinyint(6) NOT NULL DEFAULT 1,
  `outstanding_principal` decimal(10,2) NOT NULL,
  `create_date` timestamp(6) NULL DEFAULT NULL ON UPDATE current_timestamp(6),
  `create_user` varchar(35) NOT NULL,
  `update_user` varchar(35) DEFAULT NULL,
  `update_date` timestamp(6) NULL DEFAULT NULL ON UPDATE current_timestamp(6),
  `status_id` int(10) NOT NULL DEFAULT 1,
  `purpose_id` int(10) DEFAULT NULL,
  `minimum_installment` decimal(10,2) DEFAULT 0.00,
  `item_full_price` decimal(10,2) DEFAULT 0.00,
  `price_loan_percentage` decimal(10,2) DEFAULT 0.00,
  `loan_type_id` int(10) DEFAULT NULL,
  `auth_date` timestamp(6) NULL DEFAULT NULL ON UPDATE current_timestamp(6),
  `auth_user` varchar(35) DEFAULT NULL,
  `admin_fee` decimal(10,2) DEFAULT 0.00,
  `cbc_fee` decimal(10,2) DEFAULT 0.00,
  `lawyer_fee` decimal(10,2) DEFAULT 0.00,
  `inactive` tinyint(6) NOT NULL DEFAULT 0,
  `special_remarks` varchar(350) DEFAULT NULL,
  `principal_paid` decimal(10,2) DEFAULT 0.00,
  `interest_due` decimal(10,2) DEFAULT 0.00,
  `interest_paid` decimal(10,2) DEFAULT 0.00,
  `borrower_code` varchar(25) DEFAULT NULL,
  `penalty_due` decimal(10,2) DEFAULT 0.00,
  `penalty_fee` decimal(10,2) DEFAULT 0.00,
  `currency` varchar(5) DEFAULT 'USD',
  `diff_amount` decimal(10,2) DEFAULT 0.00,
  `os_interest_date` date DEFAULT NULL,
  `finish_date` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `remarks` varchar(250) DEFAULT NULL,
  `discount_amount` decimal(10,2) DEFAULT NULL,
  `adjust_principal` decimal(10,2) DEFAULT 0.00,
  `adjust_interest` decimal(10,2) DEFAULT 0.00,
  `discount_principal` decimal(10,2) DEFAULT 0.00,
  `create_uid` int(11) DEFAULT NULL,
  `pmt_count` int(11) DEFAULT 0,
  `principal_discount` decimal(10,2) DEFAULT 0.00,
  `principal_discount_percent` decimal(10,2) DEFAULT 0.00,
  `student_code` varchar(25) DEFAULT NULL,
  `program_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15217 DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of loans
-- ----------------------------

